css:
*{box-sizing:border-box}
body{margin:0;background:#fff;color:#17202a;font-family:var(--page-sans),sans-serif;font-size:16px;line-height:1.7;word-break:keep-all;overflow-wrap:break-word}
.hr-skip{position:absolute;left:-999px;top:0;background:#2563eb;color:#fff;padding:8px 12px;z-index:10}
.hr-skip:focus{left:8px;top:8px}
a{color:#2563eb}
a:focus-visible,summary:focus-visible{outline:3px solid #2563eb;outline-offset:3px;border-radius:4px}
.hr-wrap{max-width:680px;margin:0 auto;padding:0 20px}
.hr-wrap.hr-wide{max-width:860px}
.hr-top{position:sticky;top:0;background:rgba(255,255,255,.94);border-bottom:1px solid #e3e8ef;z-index:5}
.hr-topin{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;padding-top:10px;padding-bottom:10px;max-width:860px}
.hr-name{font-weight:700}
.hr-top nav{display:flex;gap:4px 16px;flex-wrap:wrap;font-size:14px}
.hr-top nav a{color:#17202a;text-decoration:none;padding:2px 0}
.hr-top nav a:hover{color:#2563eb}
.hr-label{font-family:var(--page-mono),monospace;font-size:13px;letter-spacing:.02em;color:#2563eb;margin:0 0 12px}
h1,h2,h3{font-family:var(--page-display),var(--page-sans),sans-serif;line-height:1.2;margin:0}
h1{font-size:clamp(40px,10vw,68px);font-weight:700;letter-spacing:-.02em}
h1 em{font-style:normal;color:#2563eb}
h2{font-size:clamp(24px,5vw,32px);letter-spacing:-.01em;margin-bottom:16px;line-height:1.3}
h3{font-size:18px}
.hr-hero{padding:64px 0 56px}
.hr-lead{font-size:18px;margin:20px 0 32px;max-width:34em}
.hr-big{list-style:none;margin:0 0 32px;padding:0;display:grid;grid-template-columns:repeat(3,1fr);gap:0;border-top:2px solid #17202a}
.hr-big li{padding:16px 12px 0 0;display:block}
.hr-big li+li{padding-left:14px;border-left:1px solid #e3e8ef}
.hr-n{display:block;font-family:var(--page-mono),monospace;font-size:clamp(30px,8vw,48px);font-weight:700;line-height:1.1;color:#2563eb}
.hr-n small{font-size:.4em;margin-left:2px;color:#17202a}
.hr-c{display:block;font-size:13px;line-height:1.5;color:#4a5565;margin-top:6px}
.hr-race{display:block;background:#f3f6fd;border-radius:10px;padding:16px}
.hr-lane{display:flex;align-items:center;gap:12px}
.hr-lane+.hr-lane{margin-top:10px}
.hr-lt{flex:0 0 96px;font-family:var(--page-mono),monospace;font-size:12px;color:#4a5565}
.hr-lt.hr-now{color:#17202a;font-weight:700}
.hr-track{display:block;flex:1;height:10px;background:#dbe5fb;border-radius:5px;overflow:hidden}
.hr-fill{display:block;height:100%;width:100%;transform-origin:left;transform:scaleX(0);border-radius:5px;animation:hr-load 3.8s ease-out infinite}
.hr-slow{background:#8a97ad}
.hr-fast{background:#2563eb;animation-duration:1.9s;animation-name:hr-load2}
@keyframes hr-load{0%{transform:scaleX(0)}100%,100%{transform:scaleX(1)}}
@keyframes hr-load2{0%{transform:scaleX(0)}100%{transform:scaleX(1)}}
.hr-sec{padding:72px 0}
.hr-tint{background:#f3f6fd}
.hr-p{margin:0 0 16px}
.hr-note{font-size:13px;color:#4a5565;margin:16px 0 0}
.hr-rows{list-style:none;margin:28px 0 0;padding:0;border-top:1px solid #17202a}
.hr-rows li{border-bottom:1px solid #e3e8ef}
.hr-rows a{display:grid;grid-template-columns:96px 1fr auto;gap:4px 16px;align-items:center;padding:16px 8px;color:#17202a;text-decoration:none}
.hr-rows a:hover{background:#f3f6fd}
.hr-tag{font-family:var(--page-mono),monospace;font-size:12px;color:#2563eb}
.hr-k small{font-size:12px;color:#4a5565;margin-left:4px}
.hr-v{font-family:var(--page-mono),monospace;text-align:right;white-space:nowrap}
.hr-v s{color:#6b7686}
.hr-v b{color:#2563eb;font-size:18px}
.hr-bar{display:block;grid-column:2/4;height:6px;background:#e3e8ef;border-radius:3px;overflow:hidden}
.hr-bar i{display:block;height:100%;background:#2563eb;border-radius:3px}
.hr-cs{margin:24px 0}
.hr-cs div{display:grid;grid-template-columns:96px 1fr;gap:12px;padding:14px 0;border-top:1px solid #d3dcee}
.hr-cs dt{font-family:var(--page-mono),monospace;font-size:13px;color:#2563eb;padding-top:3px}
.hr-cs dd{margin:0}
.hr-fig{margin:24px 0;padding:18px;background:#fff;border:1px solid #d3dcee;border-radius:10px}
.hr-fig figcaption{font-family:var(--page-mono),monospace;font-size:12px;color:#4a5565;margin-bottom:12px}
.hr-js{display:flex;align-items:center;gap:12px}
.hr-js+.hr-js{margin-top:8px}
.hr-jl{flex:0 0 52px;font-size:13px}
.hr-jt{display:block;flex:1}
.hr-jt i{display:block;font-style:normal;font-family:var(--page-mono),monospace;font-size:12px;color:#fff;padding:3px 10px;border-radius:4px;white-space:nowrap}
.hr-j1{width:100%;background:#8a97ad}
.hr-j2{width:43%;background:#2563eb}
.hr-det{border-top:1px solid #d3dcee;padding-top:12px}
.hr-det summary{cursor:pointer;font-weight:600}
.hr-det p{margin:10px 0 0}
.hr-steps{list-style:none;margin:28px 0 0;padding:0;position:relative}
.hr-steps::before{content:"";position:absolute;left:15px;top:10px;bottom:10px;width:2px;background:#cfdcfa}
.hr-steps li{display:flex;gap:16px;padding:0 0 22px;position:relative}
.hr-sn{flex:0 0 32px;height:32px;border-radius:50%;background:#2563eb;color:#fff;font-family:var(--page-mono),monospace;font-size:14px;display:flex;align-items:center;justify-content:center}
.hr-steps h3{margin-bottom:2px}
.hr-steps p{margin:0}
.hr-out{margin:8px 0 0;padding:16px 18px;background:#f3f6fd;border-left:4px solid #2563eb;border-radius:0 8px 8px 0}
.hr-out b{font-family:var(--page-mono),monospace;color:#2563eb;margin-left:6px}
.hr-out small{color:#4a5565}
.hr-stack{margin:24px 0 0}
.hr-stack div{display:grid;grid-template-columns:110px 1fr;gap:12px;padding:12px 0;border-top:1px solid #e3e8ef}
.hr-stack dt{font-weight:700}
.hr-stack dd{margin:0}
.hr-y{font-family:var(--page-mono),monospace;font-size:13px;color:#2563eb;margin-right:8px;white-space:nowrap}
.hr-side{padding:18px 0;border-top:1px solid #d3dcee}
.hr-side h3 small{display:block;font-family:var(--page-mono),monospace;font-size:12px;font-weight:400;color:#4a5565;margin-top:2px}
.hr-side p{margin:8px 0 0}
.hr-foot{padding:32px 0 48px;border-top:1px solid #e3e8ef}
.hr-foot p{margin:0}
@media(max-width:560px){
.hr-hero{padding:40px 0}
.hr-sec{padding:52px 0}
.hr-big{grid-template-columns:1fr}
.hr-big li{display:flex;align-items:baseline;gap:12px;padding:12px 0}
.hr-big li+li{padding-left:0;border-left:0;border-top:1px solid #e3e8ef}
.hr-n{flex:0 0 120px}
.hr-c{margin:0}
.hr-lt{flex-basis:84px}
.hr-rows a{grid-template-columns:1fr auto}
.hr-tag{grid-column:1/3}
.hr-bar{grid-column:1/3}
.hr-cs div,.hr-stack div{grid-template-columns:1fr;gap:2px}
}
@media(prefers-reduced-motion:reduce){.hr-fill{animation:none;transform:scaleX(1)}.hr-slow{width:100%}.hr-fast{width:50%}}
